#define PI 3.14159

#define ROWS 5
#define NB_BALLS_PER_ROW 13
#define ROTATION_ANGLE PI/7.0*iTime


float ballProximity(float radius, float time, vec2 fragCoord)
{
    float proximity = 0.0;
	vec2 circleCenter = vec2(0.0,0.0);

    //New galaxy center position
    circleCenter = vec2(cos(time)*radius , sin(time)*radius);

    //squeeze the galaxy vertically
    circleCenter /= vec2(5.0,5.5);

    float cosRot = cos(ROTATION_ANGLE);
    float sinRot = sin(ROTATION_ANGLE);
    //Rotate
    circleCenter = vec2(cosRot* circleCenter.x+sin(iTime*1.01) * -sinRot*circleCenter.y*sin(iTime*1.01),
    					sinRot*circleCenter.x+sin(iTime*1.01) / cosRot*circleCenter.y*sin(iTime*1.01));

    //Center on the screen
    circleCenter += vec2(iResolution.x/2.0,iResolution.y/2.0);

    proximity = distance(fragCoord, circleCenter);

    ///lol looks like eyes without this line commented
    //proximity -= distance(fragCoord, (iResolution.xy/2.0))/50.0;
    return 2.0/proximity;
}



void mainImage(out vec4 O, vec2 U) {    
    vec3  R = iResolution, 
          D = normalize( vec3( U+U, -3.5*R.y ) - R ),
          p = iTime*(0./R-2.)-.7,
          T = vec3(3.4,.6,1);


    float proximity = abs(3.0/(U.y - iResolution.x/2.0));
    vec3 col = vec3(0.0);

    float time= (1.1*iTime);
    float radius = 100.0;
    float lightReduce = 0.31;

    //add center of galaxy
    col = col + vec3(3.0*ballProximity(0.0, time, U));

    //add all the other planets/Suns/whateveryouwant
    for(int i = 0; i < ROWS; i++)
    {

        for(int j = 0; j < NB_BALLS_PER_ROW; j++)
        {
            col = col + vec3(lightReduce*ballProximity(radius, time*10. + (2.0*PI*float(j))/ float(NB_BALLS_PER_ROW), U));
          }

        radius = radius*1.51;
    	time = time/2.0;
        lightReduce *= 1.20;
    }
    col*=vec3(0.7,0.7,3.);
    O-=O;
    D.zy*=mat2(cos(iTime),sin(iTime), -sin(iTime) ,cos(iTime));
    O.xyz+=col;
    for ( float l,i=0.; i++ < 20.; p += D )
        R = fract(p) - texture(iChannel0,p/32.).rgb,
        l = .01* i / length( R - dot(R,D)*D ),  
        O.rgb += T * min( 1e3, l*l*l*col.x )/i/i,
        T /= exp( max(0., texture(iChannel1,p/128.).a -.67) * vec3(1.5,1,1) );
    O = sqrt(O); 
}
